    private void await(BooleanSupplier condition)throws Exception {await(12000,condition);}
    private void await(long limit,BooleanSupplier condition)throws Exception {long end=SystemClock.elapsedRealtime()+limit;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)SystemClock.sleep(20);assertTrue(step,condition.getAsBoolean());}
