    private long session(Store store,long start,boolean ended){ContentValues v=new ContentValues();v.put("start",start);if(ended)v.put("end",start+13670);v.put("active_ms",13670);v.put("source","tracked");v.put("origin","local");v.put("zone","UTC");v.put("sensor",SensorProvenance.MOTION);return store.getWritableDatabase().insertOrThrow("sessions",null,v);}
    private List<String> baseRows(Store s){return List.of(s.rows("SELECT * FROM sessions ORDER BY id").toString(),s.rows("SELECT * FROM epochs ORDER BY id").toString(),s.rows("SELECT * FROM sound_events ORDER BY id").toString(),s.rows("SELECT * FROM clips ORDER BY id").toString(),s.rows("SELECT * FROM alarms ORDER BY id").toString());}
    private AdditionalSoundStore.Snapshot snapshot(Records.Factory f,long id){try(Store s=f.open(c)){return AdditionalSoundStore.read(s,id);}}
    private AdditionalSoundNight own(AdditionalSoundNight n){assertNotNull(n);nights.add(n);return n;}
    private long feed(AdditionalSoundNight n,AdditionalSoundNight.Segment segment,short[] pcm,int samples,long at){long maximum=0;short[] frame=new short[320];for(int offset=0;offset<samples;){int take=Math.min(frame.length,samples-offset);for(int j=0;j<take;j++)frame[j]=pcm[(offset+j)%pcm.length];long began=SystemClock.elapsedRealtimeNanos();n.accept(segment,frame,take,at+offset/16L);maximum=Math.max(maximum,SystemClock.elapsedRealtimeNanos()-began);offset+=take;}Arrays.fill(frame,(short)0);return maximum;}
    private void releaseAll()throws Exception {for(AdditionalSoundNight n:nights)n.finish(true);for(AdditionalSoundNight n:nights){step="derived worker termination";await(n::released);}}
